CREATE FUNCTION auditoria.fn_calcular_score(p_execucao bigint) RETURNS numeric
    LANGUAGE plpgsql
    AS $$

DECLARE

    v_total NUMERIC;

BEGIN

    SELECT
        COALESCE(SUM(peso),0)
    INTO v_total
    FROM auditoria.resultado r
         INNER JOIN auditoria.item i
             ON i.id_item = r.id_item
    WHERE r.id_execucao = p_execucao
      AND r.status='OK';

    RETURN v_total;

END;

$$;


