--

CREATE FUNCTION auditoria.fn_classificacao_score(p_score numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN

    IF p_score >= 98 THEN
        RETURN 'EXCELENTE';
    ELSIF p_score >= 95 THEN
        RETURN 'MUITO BOM';
    ELSIF p_score >= 90 THEN
        RETURN 'BOM';
    ELSIF p_score >= 80 THEN
        RETURN 'REGULAR';
    ELSIF p_score >= 70 THEN
        RETURN 'ATENCAO';
    ELSE
        RETURN 'CRITICO';
    END IF;

END;
$$;


