--

CREATE FUNCTION auditoria.fn_prioridade(p_criticidade character varying) RETURNS smallint
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN CASE UPPER(TRIM(p_criticidade))

        WHEN 'CRITICA'      THEN 1
        WHEN 'ALTA'         THEN 2
        WHEN 'MEDIA'        THEN 3
        WHEN 'BAIXA'        THEN 4
        ELSE 5

    END;

END;
$$;


