CREATE PROCEDURE auditoria.sp_executar_regra(IN p_execucao bigint, IN p_regra bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

    v_sql TEXT;

    v_regra auditoria.regra%ROWTYPE;

BEGIN

    SELECT *

    INTO v_regra

    FROM auditoria.regra

    WHERE id_regra=p_regra;

