CREATE PROCEDURE auditoria.sp_iniciar_execucao(IN p_schema character varying, IN p_versao_script character varying, IN p_observacao text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
BEGIN

    INSERT INTO auditoria.execucao
    (
        versao_banco,
        versao_script,
        schema_auditado,
        usuario_execucao,
        host_execucao,
        banco,
        data_inicio,
        status_execucao,
        observacao,
        created_at,
        versao
    )
    VALUES
    (
        current_setting('server_version'),
        p_versao_script,
        p_schema,
        CURRENT_USER,
        COALESCE(inet_client_addr()::TEXT,'LOCALHOST'),
        current_database(),
        CURRENT_TIMESTAMP,
        'EXECUTANDO',
        p_observacao,
        CURRENT_TIMESTAMP,
        1
    );

END;
$$;


